cd /workspace/results/baseline63; python3 -I - <<'EOF'
import json,glob,os,statistics as st
for f in sorted(glob.glob('validation/*.jsonl'),key=lambda p:int(os.path.basename(p).split('.')[0])):
    rows=[json.loads(l) for l in open(f)]
    print("\n==",f,"n=",len(rows))
    if not rows: continue
    print("keys:",list(rows[0].keys()))
    sc=[r.get('score') for r in rows if isinstance(r.get('score'),(int,float))]
    if sc: print("score mean=%.4f  n=%d  nonzero=%d"%(st.mean(sc),len(sc),sum(1 for s in sc if s>0)))
    # look for nested reward info
    for key in ['reward_extra_info','extra_info','reward','acc','num_turns','context_budget_exhausted','tool_error']:
        vals=[r.get(key) for r in rows if key in r]
        if vals: print(key,"-> sample:",json.dumps(vals[0])[:300])
    lens=[len(r.get('output','') or '') for r in rows]
    if lens: print("output char len: mean=%.0f min=%d max=%d"%(st.mean(lens),min(lens),max(lens)))
EOF

